begin;
create table public.creator_support_requests(id uuid primary key default gen_random_uuid(),creator_user_id uuid not null references auth.users(id) on delete cascade,category text not null,subject text not null,details text not null,status text not null default 'open',priority text not null default 'standard',created_at timestamptz not null default now(),updated_at timestamptz not null default now());alter table public.creator_support_requests enable row level security;
create policy "creator support own" on public.creator_support_requests for all using(creator_user_id=auth.uid()) with check(creator_user_id=auth.uid());
create or replace function public.get_public_creator_plan(p_user_id uuid) returns text language sql security definer set search_path=public stable as $$ select case when plan_code='creator_plus' and status='active' then 'creator_plus' when plan_code='founding_beta' then 'founding_creator' else 'creator_free' end from account_entitlements where user_id=p_user_id $$;grant execute on function public.get_public_creator_plan(uuid) to anon,authenticated;
create or replace function public.get_my_creator_activity(p_days int default 90) returns jsonb language sql security definer set search_path=public stable as $$ select jsonb_build_object('followers',(select count(*) from identity_follows f join account_identities t on t.id=f.target_identity_id where t.subject_user_id=auth.uid() and f.created_at>=now()-make_interval(days=>least(greatest(p_days,1),365))),'likes',(select count(*) from identity_reactions r where r.entity_id=auth.uid() and r.reaction_type='like' and r.created_at>=now()-make_interval(days=>least(greatest(p_days,1),365))),'saves',(select count(*) from identity_reactions r where r.entity_id=auth.uid() and r.reaction_type='save' and r.created_at>=now()-make_interval(days=>least(greatest(p_days,1),365))),'comments',(select count(*) from identity_comments c where c.entity_id=auth.uid() and c.created_at>=now()-make_interval(days=>least(greatest(p_days,1),365)))) $$;grant execute on function public.get_my_creator_activity(int) to authenticated;
commit;

